void action()
{
while (true) {
cout << "어떻게 할까요:\0" ;     // 행동율 요구
string act;
cin >> act;         // 문자열에 문자를 읽기
Point delta {0,0); // Pointof {x,y} 쌍을 저장
for (char ch : act) {
switch (ch) {
case 'u': // 위로
case 'n': // 북쪽으로
++delta.y;
break;
case 'r': // 오른쪽으로
case 'e': // 동쪽으로
++delta.x;
break;
// ... 다른 행동 .
default:
cout << "가만히 YAGLCH\n";
}
move( current+delta*scale);
update_display();
}
}
}

